/* ===================== BÀI 14 · Nhiệt, công suất động P≈αCV²f và công suất rò ===================== */
/* Bài 14 · Nhiệt, công suất động P≈αCV²f và công suất rò (CM01.07) — sinh bởi tools/author/maytinh/m14.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l14"),{id:"l14",scenarios:[{"label": "Ví dụ: Tính công suất động", "note": "P ≈ αCV²f với thông số giả định của một chip.", "steps": [{"t": "Giả định: α = 0,1; C = 100 nF; V = 1,0 V; f = 3 GHz", "html": "<p class=\"mt-calc\">α: tỉ lệ điện dung đổi trạng thái mỗi chu kỳ · C: tổng điện dung có thể chuyển mạch của chip · V: điện áp nguồn · f: xung nhịp<\/p>", "say": "<p>C ở đây là tổng điện dung hiệu dụng của cả chip, số giả định để ra một con số dễ hình dung.<\/p>"}, {"t": "P_động = 0,1 × 10⁻⁷ × 1² × 3 × 10⁹ = 30 W", "html": "<p class=\"mt-calc\">P<sub>động<\/sub> ≈ α·C·V²·f = 0,1 × 100 × 10⁻⁹ × 1,0² × 3 × 10⁹ = <b>30 W<\/b><\/p>", "ask": {"q": "Giữ mọi thứ, chỉ giảm α từ 0,1 xuống 0,05 (chip bận ít hơn). Công suất động còn bao nhiêu?", "o": ["30 W", "15 W", "7,5 W"], "a": 1}}, {"t": "Vì sao có V²: mỗi lần nạp rồi xả, nguồn mất C·V²", "html": "<p class=\"mt-calc\">Nạp tụ C lên V: nguồn cấp C·V², tụ giữ ½C·V², điện trở của transistor tỏa ½C·V²; xả về 0: ½C·V² còn lại cũng thành nhiệt<\/p>", "say": "<p>Mỗi chu kỳ nạp – xả biến C·V² năng lượng thành nhiệt, không phụ thuộc transistor nhanh hay chậm. Nhân với số lần mỗi giây (α·f) ra công suất.<\/p>"}]}, {"label": "Ví dụ: Hạ xung nhịp và điện áp (DVFS)", "note": "Giảm 20% cả f và V: công suất còn khoảng một nửa.", "steps": [{"t": "Chip chạy 3 GHz ở 1,0 V: 30 W", "html": "<div class=\"mt-bars\"><div><span>3 GHz, 1,0 V<\/span><span><i class=\"w\" style=\"width:93.8%\"><\/i><em>30 W<\/em><\/span><\/div><\/div>", "say": "<p>Khi tải nhẹ, không cần chạy hết tốc độ.<\/p>"}, {"t": "Hạ xuống 2,4 GHz và 0,8 V: 15,36 W", "html": "<p class=\"mt-calc\">0,8² × 0,8 = 0,512 → 30 × 0,512 = <b>15,36 W<\/b><\/p><div class=\"mt-bars\"><div><span>3 GHz, 1,0 V<\/span><span><i class=\"w\" style=\"width:93.8%\"><\/i><em>30 W<\/em><\/span><\/div><div><span>2,4 GHz, 0,8 V<\/span><span><i class=\"o\" style=\"width:48.0%\"><\/i><em>15,36 W<\/em><\/span><\/div><\/div>", "ask": {"q": "Giảm xung nhịp 20% và điện áp 20%. Công suất động giảm còn khoảng bao nhiêu phần trăm?", "o": ["80%", "64%", "Khoảng 51%"], "a": 2}}, {"t": "Đó là DVFS", "html": "<p class=\"mt-calc\">Tốc độ còn 80%, công suất còn khoảng 51%<\/p>", "say": "<p>Điều chỉnh điện áp và tần số động: CPU tự hạ xung nhịp và điện áp khi rảnh, tăng khi bận. Vì vậy xung nhịp hiển thị trong Task Manager thay đổi liên tục (Chương 6, Chương 16).<\/p>"}]}, {"label": "Ví dụ: Công suất rò khi đứng yên", "note": "Rò không phụ thuộc xung nhịp.", "steps": [{"t": "Chip đứng yên vẫn tốn điện", "html": "<p class=\"mt-calc\">Giả định dòng rò tổng I<sub>rò<\/sub> = 5 A ở 1,0 V và 50 °C → P<sub>rò<\/sub> = V · I = <b>5 W<\/b><\/p>", "say": "<p>Công suất rò không phụ thuộc xung nhịp: kể cả khi không có transistor nào chuyển mạch (Bài 11).<\/p>"}, {"t": "Tổng công suất = động + rò", "html": "<p class=\"mt-calc\">Đang chạy: 30 + 5 = 35 W · đứng yên (α ≈ 0): khoảng 5 W<\/p><div class=\"mt-bars\"><div><span>Động<\/span><span><i class=\"w\" style=\"width:85.7%\"><\/i><em>30 W<\/em><\/span><\/div><div><span>Rò<\/span><span><i class=\"e\" style=\"width:14.3%\"><\/i><em>5 W<\/em><\/span><\/div><\/div>", "ask": {"q": "Chip ngừng chuyển mạch hoàn toàn (α = 0). Công suất còn lại là gì?", "o": ["Bằng 0", "Công suất rò", "Vẫn 30 W"], "a": 1}, "say": "<p>Để giảm rò khi rảnh, chip tắt hẳn nguồn của các khối không dùng (tắt nguồn từng khối). Các trạng thái ngủ sâu của CPU dựa trên kỹ thuật này.<\/p>"}]}, {"label": "Ví dụ: Nhiệt độ chip theo công suất và tản nhiệt", "note": "T_j ≈ T_a + P·θ.", "steps": [{"t": "Mô hình: T_j ≈ T_a + P × θ", "html": "<p class=\"mt-calc\">T<sub>j<\/sub>: nhiệt độ chip · T<sub>a<\/sub>: nhiệt độ không khí · θ: nhiệt trở từ chip ra không khí (°C/W)<\/p>", "say": "<p>Mô hình một nhiệt trở cho nhiệt độ ổn định sau khi chạy đủ lâu; bỏ qua thời gian nóng lên. θ nhỏ nghĩa là tản nhiệt tốt.<\/p>"}, {"t": "35 W, θ = 0,4 °C/W, T_a = 30 °C → 44 °C", "html": "<p class=\"mt-calc\">30 + 35 × 0,4 = <b>44 °C<\/b><\/p><div class=\"mt-bars\"><div><span>35 W<\/span><span><i class=\"o\" style=\"width:31.4%\"><\/i><em>44 °C<\/em><\/span><\/div><\/div>"}, {"t": "100 W, cùng tản nhiệt → 70 °C", "html": "<p class=\"mt-calc\">30 + 100 × 0,4 = <b>70 °C<\/b><\/p><div class=\"mt-bars\"><div><span>35 W<\/span><span><i class=\"o\" style=\"width:31.4%\"><\/i><em>44 °C<\/em><\/span><\/div><div><span>100 W<\/span><span><i class=\"w\" style=\"width:50.0%\"><\/i><em>70 °C<\/em><\/span><\/div><\/div>", "ask": {"q": "T_a = 30 °C, θ = 0,4 °C/W, P = 100 W. Nhiệt độ chip khoảng bao nhiêu?", "o": ["40 °C", "70 °C", "130 °C"], "a": 1}}, {"t": "Tản nhiệt kém (θ = 1,0) → 130 °C: chip phải giảm tốc", "html": "<p class=\"mt-calc\">30 + 100 × 1,0 = <b>130 °C<\/b>, vượt giới hạn giả định 100 °C<\/p><div class=\"mt-bars\"><div><span>θ = 0,4<\/span><span><i class=\"w\" style=\"width:50.0%\"><\/i><em>70 °C<\/em><\/span><\/div><div><span>θ = 1,0<\/span><span><i class=\"e\" style=\"width:92.9%\"><\/i><em>130 °C<\/em><\/span><\/div><\/div>", "say": "<p>Khi chạm giới hạn nhiệt, chip tự hạ xung nhịp và điện áp (giảm tốc vì nhiệt) để giảm P. Giới hạn thật của từng chip do nhà sản xuất công bố; không có một ngưỡng chung cho mọi CPU.<\/p>"}]}, {"label": "Bẫy: Nhiệt và rò khuếch đại nhau", "note": "Quy luật rò gấp đôi mỗi 20 °C là giả định minh họa.", "steps": [{"t": "Giả định: rò 5 W ở 50 °C, gấp đôi mỗi khi nóng thêm 20 °C", "html": "<p class=\"mt-calc\">Công suất động 40 W, T_a = 30 °C. Quy luật rò theo nhiệt là giả định minh họa; chip thật có đặc tính riêng<\/p>", "say": "<p>Dòng rò của transistor tăng mạnh theo nhiệt độ. Nhiệt làm rò tăng, rò làm nhiệt tăng: một vòng phản hồi dương.<\/p>"}, {"t": "Tản nhiệt tốt (θ = 0,8): ổn định quanh 70 °C", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Vòng<\/th><th scope=\"col\">Rò (W)<\/th><th scope=\"col\">T_j (°C)<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>2,5<\/td><td>64<\/td><\/tr><tr><td>2<\/td><td>8,1<\/td><td>68,5<\/td><\/tr><tr><td>3<\/td><td>9,5<\/td><td>69,6<\/td><\/tr><tr><td>4<\/td><td>9,9<\/td><td>69,9<\/td><\/tr><tr><td>5<\/td><td>10<\/td><td>70<\/td><\/tr><\/tbody><\/table>"}, {"t": "Tản nhiệt kém (θ = 1,2): nhiệt tăng không dừng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Vòng<\/th><th scope=\"col\">Rò (W)<\/th><th scope=\"col\">T_j (°C)<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>2,5<\/td><td>81<\/td><\/tr><tr><td>2<\/td><td>14,6<\/td><td>96<\/td><\/tr><tr><td>3<\/td><td>24,3<\/td><td>107<\/td><\/tr><tr><td>4<\/td><td>36,2<\/td><td>121<\/td><\/tr><tr><td>5<\/td><td>59,4<\/td><td class=\"bad\">149<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Với tản nhiệt kém, vòng nhiệt – rò dẫn tới điều gì nếu chip không tự giảm tốc?", "o": ["Nhiệt độ tự ổn định ở 30 °C", "Nhiệt độ tăng mãi (mất ổn định nhiệt)", "Rò giảm dần"], "a": 1}, "say": "<p>Đây là mất ổn định nhiệt trong mô hình. Chip thật có cảm biến nhiệt và tự giảm tốc hoặc tắt máy trước khi hỏng; vì vậy bảo trì tản nhiệt quan trọng với máy chạy liên tục.<\/p>"}]}, {"label": "Lỗi: Bỏ qua bụi và keo tản nhiệt khô", "note": "θ tăng làm nhiệt độ tăng dù công suất không đổi.", "steps": [{"t": "Máy mới: θ = 0,4 °C/W, 100 W → 70 °C", "html": "<div class=\"mt-bars\"><div><span>Máy mới<\/span><span><i class=\"o\" style=\"width:50.0%\"><\/i><em>70 °C<\/em><\/span><\/div><\/div>", "say": "<p>Quạt sạch, keo tản nhiệt còn tốt.<\/p>"}, {"t": "Sau vài năm: bụi bám, keo khô → θ tăng (giả định 0,9)", "html": "<p class=\"mt-calc\">30 + 100 × 0,9 = <b>120 °C<\/b><\/p><div class=\"mt-bars\"><div><span>Máy mới<\/span><span><i class=\"o\" style=\"width:50.0%\"><\/i><em>70 °C<\/em><\/span><\/div><div><span>Bụi, keo khô<\/span><span><i class=\"e\" style=\"width:85.7%\"><\/i><em>120 °C<\/em><\/span><\/div><\/div>", "ask": {"q": "Cùng công suất 100 W, θ tăng từ 0,4 lên 0,9 °C/W. Máy sẽ thế nào?", "o": ["Mát hơn", "Nóng hơn nhiều, có thể bị giảm tốc vì nhiệt", "Không đổi"], "a": 1}}, {"t": "Sửa: vệ sinh, thay keo theo quy trình an toàn", "html": "<p class=\"mt-calc\">Tắt máy, rút điện, chống tĩnh điện; với máy công nghiệp làm theo hướng dẫn nhà sản xuất (Chương 16, Chương 19)<\/p>", "say": "<p>“Máy chậm dần theo năm” đôi khi là do nhiệt chứ không do phần mềm. Đo nhiệt độ và xung nhịp (bằng HWiNFO ở các chương sau) trước khi kết luận.<\/p>"}]}, {"label": "Lỗi: Coi TDP là công suất tối đa", "note": "TDP là thông số thiết kế tản nhiệt, định nghĩa theo hãng.", "steps": [{"t": "Hiểu lầm: TDP là công suất lớn nhất chip có thể tiêu thụ", "html": "<p class=\"mt-calc\">TDP (thermal design power): công suất mà bộ tản nhiệt cần được thiết kế để tản trong điều kiện do hãng định nghĩa<\/p>", "say": "<p>Mỗi hãng định nghĩa TDP theo cách riêng; nhiều CPU được phép vượt mức này trong thời gian ngắn khi tăng tốc.<\/p>"}, {"t": "Chip có thể vượt TDP trong thời gian ngắn", "html": "<p class=\"mt-calc\">Ví dụ minh họa: TDP 65 W nhưng có giới hạn công suất ngắn hạn cao hơn, nếu nhiệt và nguồn cho phép<\/p>", "ask": {"q": "CPU ghi TDP 65 W. Kết luận nào an toàn?", "o": ["CPU không bao giờ dùng quá 65 W", "Bộ nguồn 65 W là đủ cho cả máy", "Cần xem tài liệu hãng về các giới hạn công suất, không coi TDP là mức tối đa"], "a": 2}}, {"t": "Sửa: chọn tản nhiệt và nguồn theo tài liệu và phép đo", "html": "<p class=\"mt-calc\">Tra giới hạn công suất trong tài liệu hãng; đo công suất, nhiệt độ thực tế dưới tải<\/p>", "say": "<p>Chương 16 học kỹ TDP, giới hạn công suất và cách chọn bộ nguồn.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l14"),"l14",[{"kind": "num", "t": "Công suất động", "d": "<p>P ≈ α·C·V²·f. Làm tròn 2 chữ số thập phân.<\/p>", "items": [{"q": "α = 0,2; C = 50 nF; V = 1,0 V; f = 2 GHz. P?", "a": 20.0, "tol": 0.01, "unit": "W"}, {"q": "α = 0,1; C = 100 nF; V = 1,2 V; f = 3 GHz. P?", "a": 43.2, "tol": 0.01, "unit": "W"}, {"q": "Giảm V từ 1,0 V xuống 0,7 V, giữ các yếu tố khác. P còn bao nhiêu lần?", "a": 0.49, "tol": 0.001}, {"q": "Năng lượng mỗi chu kỳ nạp – xả của tụ 2 fF ở 1 V (đơn vị fJ)?", "a": 2, "tol": 0.001, "unit": "fJ"}], "hints": ["Đổi nF = 10⁻⁹ F, GHz = 10⁹ Hz trước khi nhân.", "Câu 2: 0,1 × 10⁻⁷ × 1,44 × 3 × 10⁹.", "Năng lượng mỗi chu kỳ = C·V²."], "why": "0,2 × 5·10⁻⁸ × 1 × 2·10⁹ = 20 W; 0,1 × 10⁻⁷ × 1,44 × 3·10⁹ = 43,2 W; 0,7² = 0,49; 2 fF × 1² = 2 fJ."}, {"kind": "num", "t": "Nhiệt độ chip", "d": "<p>T<sub>j<\/sub> ≈ T<sub>a<\/sub> + P·θ.<\/p>", "items": [{"q": "T<sub>a<\/sub> = 25 °C, P = 50 W, θ = 0,5 °C/W. T<sub>j<\/sub>?", "a": 50, "tol": 0.01, "unit": "°C"}, {"q": "T<sub>a<\/sub> = 40 °C (tủ điện nóng), P = 50 W, θ = 0,5. T<sub>j<\/sub>?", "a": 65, "tol": 0.01, "unit": "°C"}, {"q": "Giới hạn 95 °C, T<sub>a<\/sub> = 35 °C, θ = 0,6. Công suất tối đa?", "a": 100, "tol": 0.01, "unit": "W"}, {"q": "Muốn 120 W ở T<sub>a<\/sub> = 30 °C mà T<sub>j<\/sub> ≤ 90 °C. θ lớn nhất?", "a": 0.5, "tol": 0.001, "unit": "°C/W"}], "hints": ["T<sub>j<\/sub> = T<sub>a<\/sub> + P × θ.", "Đổi chiều: P = (T<sub>j<\/sub> − T<sub>a<\/sub>) ÷ θ.", "θ = (T<sub>j<\/sub> − T<sub>a<\/sub>) ÷ P."], "why": "25 + 25 = 50 °C; 40 + 25 = 65 °C (không khí nóng làm chip nóng hơn đúng bằng chênh lệch); (95 − 35)/0,6 = 100 W; (90 − 30)/120 = 0,5 °C/W."}, {"kind": "pick", "t": "Công suất động hay công suất rò?", "d": "<p>Mỗi biện pháp chủ yếu giảm loại công suất nào?<\/p>", "cats": ["Chủ yếu giảm công suất động", "Chủ yếu giảm công suất rò"], "items": [{"q": "Hạ xung nhịp khi máy rảnh", "a": 0}, {"q": "Tắt hẳn nguồn của khối không dùng (power gating)", "a": 1}, {"q": "Giảm số lần các tín hiệu đổi trạng thái (α)", "a": 0}, {"q": "Dùng transistor ngưỡng cao cho khối không cần nhanh", "a": 1}, {"q": "Giữ chip mát hơn bằng tản nhiệt tốt", "a": 1}, {"q": "Giảm điện dung dây nối nhờ thiết kế gọn", "a": 0}], "hints": ["Công suất động phụ thuộc α, C, V, f.", "Công suất rò phụ thuộc dòng rò: ngưỡng, nhiệt độ, có nguồn hay không.", "Hạ điện áp giảm cả hai, nên không có trong danh sách."], "why": "Xung nhịp, α và điện dung nằm trong P ≈ αCV²f. Tắt nguồn, ngưỡng cao, nhiệt độ thấp làm giảm dòng rò."}]);

makeQuiz("quiz14","score14",[{"q": "Theo P ≈ αCV²f, giảm điện áp 10% (các yếu tố khác giữ nguyên) thì công suất động còn khoảng bao nhiêu?", "o": ["90%", "81%", "50%", "99%"], "a": 1, "e": "0,9² = 0,81. Điện áp nằm trong bình phương nên giảm điện áp hiệu quả hơn giảm xung nhịp cùng tỉ lệ."}, {"q": "Công suất rò khác công suất động ở điểm nào?", "o": ["Rò chỉ có khi chip chạy hết tốc độ", "Rò không phụ thuộc điện áp", "Rò tồn tại cả khi không có transistor nào chuyển mạch", "Rò làm chip mát hơn"], "a": 2, "e": "Công suất động gắn với chuyển mạch; công suất rò có ngay cả khi đứng yên và tăng theo nhiệt độ."}, {"q": "T<sub>a<\/sub> = 30 °C, P = 80 W, θ = 0,5 °C/W. Nhiệt độ chip ổn định khoảng bao nhiêu?", "o": ["40 °C", "110 °C", "70 °C", "80 °C"], "a": 2, "e": "30 + 80 × 0,5 = 70 °C."}, {"q": "Giảm tốc vì nhiệt (thermal throttling) là gì?", "o": ["Chip tự hạ xung nhịp và điện áp khi chạm giới hạn nhiệt độ", "Quạt quay chậm lại", "Hệ điều hành tắt bớt chương trình", "Chip bị hỏng vĩnh viễn"], "a": 0, "e": "Giảm f và V làm P giảm, nhiệt độ giảm. Máy vẫn chạy nhưng chậm hơn: dấu hiệu cần kiểm tra tản nhiệt."}, {"q": "Vì sao nhiệt độ và dòng rò có thể tạo vòng phản hồi nguy hiểm?", "o": ["Vì rò làm chip lạnh đi", "Vì nhiệt làm rò tăng, rò làm công suất và nhiệt tăng thêm", "Vì quạt hút thêm bụi", "Vì TDP thay đổi"], "a": 1, "e": "Đó là phản hồi dương. Tản nhiệt tốt làm vòng hội tụ; tản nhiệt kém có thể làm nhiệt độ tăng mãi nếu không có cơ chế bảo vệ."}]);

